using System.Text.Json;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Media.Imaging;
using LtcPlayer.App;
namespace LtcPlayer.Avalonia;
public static class SaveLayoutVerification
{
 public static async Task RunAsync(MainWindow w,string folder)
 {
  Directory.CreateDirectory(folder);var results=new List<object>();bool failed=false;int receiving=0;string saved=Path.Combine(folder,"saved.json");
  var button=w.FindControl<Button>("SaveProgramButton")!;
  void Check(bool ok,string why){if(!ok)throw new IOException(why);}
  async Task Test(string name,Func<Task> body){try{await body();results.Add(new{test=name,status="PASS"});}catch(Exception e){failed=true;results.Add(new{test=name,status="FAIL",detail=e.ToString()});}File.WriteAllText(Path.Combine(folder,"results.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}
  async Task Until(Func<bool> condition){double end=MasterClock.Timestamp()+10;while(!condition()){if(MasterClock.Timestamp()>end)throw new TimeoutException(JsonSerializer.Serialize(new{w.LatestObservation,w.Coordinator.Audio}));await Task.Delay(10);}}
  var row=new CueRow{FilePath=Path.Combine(Program.Option("--fixtures")!,"hap-sync-30s.mov")};
  try{
   await Test("empty list disables save and rejects entry before opening picker",async()=>{bool called=false,rejected=false;try{await w.ChooseSaveForTestAsync(()=>{called=true;return Task.FromResult<string?>(saved);});}catch(InvalidOperationException){rejected=true;}Check(rejected&&!called&&!button.IsEnabled&&ToolTip.GetShowOnDisabled(button)&&ToolTip.GetTip(button)?.ToString()==w.SaveAccess.Reason&&!w.SaveAccess.Allowed&&!File.Exists(saved),"empty save opened picker or wrote file");});
   await Test("disabled rows with metadata or TC errors are still saveable",async()=>{var bad=new CueRow{FilePath="missing.mov",Enabled=false};bad.Hours="bad";bad.SourceError="missing";w.Editor.Add(bad);Check(w.SaveAccess.Allowed&&button.IsEnabled,"errors treated as empty list");await w.SaveProgramForTestAsync(saved);Check(File.ReadAllText(saved).Contains("missing.mov"),"invalid row not preserved");w.Editor.Delete(bad);Check(!w.SaveAccess.Allowed&&!button.IsEnabled,"last removal did not disable save");});
   await w.ApplySettingsAsync(new(new(Rate:"25",Freewheel:.3),VideoRenderer.Displays().First(d=>d.Primary!=0)));await ShowProgramService.RefreshAsync(row,CancellationToken.None);w.Editor.Add(row);
   foreach(var size in new[]{(W:1640,H:940),(W:1640,H:500),(W:1240,H:720)})await Test("wide panes preserve natural right-side height / "+size.W+"x"+size.H,async()=>{
    w.Width=size.W;w.Height=size.H;await Task.Delay(250);w.UpdateResponsiveLayout();await Task.Delay(100);var body=w.FindControl<Grid>("Workspace")!;var left=w.FindControl<Border>("EditorPane")!;var cover=w.FindControl<Border>("CoverPane")!;var preview=w.FindControl<Grid>("PreviewPane")!;
    double Bottom(Control c)=>c.TranslatePoint(default,body)!.Value.Y+c.Bounds.Height;
    Check(!w.CompactLayout&&Bottom(left)>=Bottom(cover)-1.1,"cover extends below list");double at=Bottom(left);await Task.Delay(120);Check(Math.Abs(Bottom(left)-at)<1,"layout did not settle");var fade=w.FindControl<NumericUpDown>("FadeSeconds")!;Check(fade.TranslatePoint(default,cover)!.Value.Y+fade.Bounds.Height<=cover.Bounds.Height,"cover controls clipped");
    if(size.H==940){using var bitmap=new RenderTargetBitmap(new PixelSize((int)w.ClientSize.Width,(int)w.ClientSize.Height),new Vector(96,96));bitmap.Render(w);bitmap.Save(Path.Combine(folder,"default-layout.png"));}
   });
   await Test("narrow panes remain stacked and cover is reachable by scrolling",async()=>{w.Width=700;w.Height=1100;await Task.Delay(250);var preview=w.FindControl<Grid>("PreviewPane")!;var scroll=w.FindControl<ScrollViewer>("WorkspaceScroll")!;Check(w.CompactLayout&&Grid.GetRow(preview)==2,"narrow layout not stacked");scroll.Offset=new Vector(0,scroll.Extent.Height);await Task.Delay(100);Check(scroll.Offset.Y>=scroll.Extent.Height-scroll.Viewport.Height-2,"cover unreachable");w.Width=1640;w.Height=940;await Task.Delay(250);});
   await w.Monitor.ConfigureAsync(new(Rate:"25",Freewheel:.3),async(clock,t)=>{double start=MasterClock.Timestamp();while(!t.IsCancellationRequested){if(Volatile.Read(ref receiving)!=0){int f=25+(int)((MasterClock.Timestamp()-start)*25)%400;clock.Accept(new TcFrame{Seconds=f/25,Frame=f%25},MasterClock.Timestamp());}await Task.Delay(20,t);}});
   await w.SetSharedAudioAsync(true,silenceForVerification:true);await w.PlayCueForTestAsync(row);
   await Test("manual playback can save with external output off and on",async()=>{var video=w.Preview.PlaybackSessionId;await w.SaveProgramForTestAsync(saved);await w.ArmAsync();await w.SaveProgramForTestAsync(saved);Check(w.SaveAccess.Allowed&&button.IsEnabled&&video==w.Preview.PlaybackSessionId&&w.IsOutputActive,"output or manual playback blocked save");});
   await Test("LOCKED and RESYNC both reject save and preserve destination",async()=>{Volatile.Write(ref receiving,1);await Until(()=>w.Coordinator.OwnsSurface&&!button.IsEnabled);string before=File.ReadAllText(saved);bool rejected=false;try{await w.SaveProgramForTestAsync(saved);}catch(InvalidOperationException){rejected=true;}Check(rejected&&!w.SaveAccess.Allowed&&File.ReadAllText(saved)==before,"LOCKED save accepted");w.Monitor.Clock.Accept(new TcFrame{Seconds=10},MasterClock.Timestamp());Check(!w.SaveAccess.Allowed,"RESYNC save accepted");});
   await Test("FREEWHEEL blocks save and LOST hold permits it without changing image",async()=>{Volatile.Write(ref receiving,0);await Until(()=>w.Monitor.Clock.Read().State==SyncState.FREEWHEEL);Check(!w.SaveAccess.Allowed,"FREEWHEEL save accepted");await Until(()=>w.Monitor.Clock.Read().State==SyncState.LOST&&button.IsEnabled);await Task.Delay(100);var pixels=w.Surface.Canvas.Readback();var sync=w.SynchronizationSession;await w.SaveProgramForTestAsync(saved);Check(w.SaveAccess.Allowed&&w.SynchronizationSession==sync&&pixels.AsSpan().SequenceEqual(w.Surface.Canvas.Readback()),"LOST save changed held source");});
   await Test("input ERROR permits saving existing data",async()=>{w.Monitor.Clock.Fault();await Until(()=>button.IsEnabled);Check(w.SaveAccess.Allowed,"input ERROR blocked recovery save");await w.SaveProgramForTestAsync(saved);});
   await Test("LTC acquisition while picker is open aborts before writing",async()=>{var gate=new TaskCompletionSource<string?>();string before=File.ReadAllText(saved);var save=w.ChooseSaveForTestAsync(()=>gate.Task);Volatile.Write(ref receiving,1);await Until(()=>w.Monitor.Clock.Read().State is SyncState.LOCKED or SyncState.RESYNC);gate.SetResult(saved);bool rejected=false;try{await save;}catch(InvalidOperationException){rejected=true;}Check(rejected&&File.ReadAllText(saved)==before&&!Directory.GetFiles(folder,"*.tmp").Any(),"picker race wrote destination");Volatile.Write(ref receiving,0);await Until(()=>w.Monitor.Clock.Read().State==SyncState.LOST&&button.IsEnabled);});
   await Test("removing last cue while picker is open aborts before writing",async()=>{var gate=new TaskCompletionSource<string?>();string before=File.ReadAllText(saved);var save=w.ChooseSaveForTestAsync(()=>gate.Task);await w.DeleteCuesAsync([row.CueId]);gate.SetResult(saved);bool rejected=false;try{await save;}catch(InvalidOperationException){rejected=true;}Check(rejected&&w.Editor.Rows.Count==0&&!button.IsEnabled&&File.ReadAllText(saved)==before,"empty picker race wrote destination");w.Editor.Add(row);});
   await Test("save already writing completes safely when LTC resumes",async()=>{var gate=new TaskCompletionSource();w.Editor.BeforeSaveWriteForTest=t=>gate.Task.WaitAsync(t);var save=w.SaveProgramForTestAsync(saved);try{Volatile.Write(ref receiving,1);await Until(()=>w.Monitor.Clock.Read().State is SyncState.LOCKED or SyncState.RESYNC);Check(!button.IsEnabled&&!save.IsCompleted,"pending save state incorrect");}finally{gate.SetResult();await save;w.Editor.BeforeSaveWriteForTest=null;}Check(File.Exists(saved)&&!w.SaveAccess.Allowed&&!Directory.GetFiles(folder,"*.tmp").Any(),"started write failed on LTC transition");});
  }catch(Exception e){failed=true;File.WriteAllText(Path.Combine(folder,"fatal.txt"),e.ToString());}
  finally{w.Editor.BeforeSaveWriteForTest=null;Volatile.Write(ref receiving,0);await w.DisarmAsync();await w.Coordinator.DisposeAsync();await w.Preview.DisposeAsync();await w.Monitor.DisposeAsync();MainWindow.Shutdown(failed?1:0);}
 }
}
